// The Putonghua syllable inventory (Hanyu Pinyin, toneless bases), as in the standard pinyin table.
// content/data/syllables.yaml adds, per base, the tones that exist and the recording keys; it is
// generated by `npm run data:import` and checked against this table by the unit tests.

export const INITIALS = ['b', 'p', 'm', 'f', 'd', 't', 'n', 'l', 'g', 'k', 'h', 'j', 'q', 'x', 'zh', 'ch', 'sh', 'r', 'z', 'c', 's'] as const;
export type Initial = (typeof INITIALS)[number] | '';

/** Finals as written after an initial (ü written as ü; after j q x it is spelled u). */
const TABLE: Record<string, string> = {
  '': 'a o e ai ei ao ou an en ang eng er',
  y: 'yi ya yo ye yao you yan yin yang ying yong yu yue yuan yun',
  w: 'wu wa wo wai wei wan wen wang weng',
  b: 'a o ai ei ao an en ang eng i ie iao ian in ing u',
  p: 'a o ai ei ao ou an en ang eng i ie iao ian in ing u',
  m: 'a o e ai ei ao ou an en ang eng i ie iao iu ian in ing u',
  f: 'a o ei ou an en ang eng u',
  d: 'a e ai ei ao ou an en ang eng ong i ie iao iu ian ing u uo ui uan un',
  t: 'a e ai ao ou an ang eng ong i ie iao ian ing u uo ui uan un',
  n: 'a e ai ei ao ou an en ang eng ong i ie iao iu ian in iang ing u uo uan ü üe',
  l: 'a o e ai ei ao ou an ang eng ong i ia ie iao iu ian in iang ing u uo uan un ü üe',
  g: 'a e ai ei ao ou an en ang eng ong u ua uo uai ui uan un uang',
  k: 'a e ai ei ao ou an en ang eng ong u ua uo uai ui uan un uang',
  h: 'a e ai ei ao ou an en ang eng ong u ua uo uai ui uan un uang',
  j: 'i ia ie iao iu ian in iang ing iong u ue uan un',
  q: 'i ia ie iao iu ian in iang ing iong u ue uan un',
  x: 'i ia ie iao iu ian in iang ing iong u ue uan un',
  zh: 'a e i ai ei ao ou an en ang eng ong u ua uo uai ui uan un uang',
  ch: 'a e i ai ao ou an en ang eng ong u ua uo uai ui uan un uang',
  sh: 'a e i ai ei ao ou an en ang eng u ua uo uai ui uan un uang',
  r: 'e i ao ou an en ang eng ong u ua uo ui uan un',
  z: 'a e i ai ei ao ou an en ang eng ong u uo ui uan un',
  c: 'a e i ai ao ou an en ang eng ong u uo ui uan un',
  s: 'a e i ai ao ou an en ang eng ong u uo ui uan un',
};

/** Interjection syllables written without a vowel (嗯 ńg, 呣 m̀, 哼 hng). Valid, but never taught. */
export const INTERJECTIONS = ['n', 'ng', 'm', 'hm', 'hng'] as const;

function build(): Map<string, { initial: Initial; final: string }> {
  const out = new Map<string, { initial: Initial; final: string }>();
  for (const [ini, finals] of Object.entries(TABLE)) {
    for (const f of finals.split(' ')) {
      if (ini === '' || ini === 'y' || ini === 'w') {
        // Zero-initial syllables: y/w are spelling, not initials.
        out.set(f, { initial: '', final: f });
      } else {
        out.set(ini + f, { initial: ini as Initial, final: f });
      }
    }
  }
  return out;
}

const SYLLABLES = build();

/** Every toneless base syllable, in table order. */
export const SYLLABLE_BASES: readonly string[] = [...SYLLABLES.keys()];

/** Lowercase, ü for v and u:, and ü spelled u after j q x y (jü → ju), as the table writes it. */
export function tableSpelling(base: string): string {
  return base.toLowerCase().replace(/v|u:/g, 'ü').replace(/^([jqxy])ü/, '$1u');
}

/** True for a toneless pinyin base on the table (ü as ü, v or u:). Interjections are not included. */
export function isValidSyllable(base: string): boolean {
  return SYLLABLES.has(tableSpelling(base));
}

export function syllableParts(base: string): { initial: Initial; final: string } | null {
  return SYLLABLES.get(tableSpelling(base)) ?? null;
}
